import { fetchKulturhusetEvents } from './src/sources/kulturhuset.js';

async function test() {
  console.log('Testing Kulturhuset TypeScript scraper...');
  try {
    const events = await fetchKulturhusetEvents({ limit: 5 });
    console.log(`\n✅ Found ${events.length} events`);
    events.forEach((ev, i) => {
      console.log(`\n--- Event ${i+1} ---`);
      console.log(`  ID: ${ev.id}`);
      console.log(`  Title: ${ev.title}`);
      console.log(`  Date: ${ev.date} ${ev.time}`);
      console.log(`  Venue: ${ev.venue}`);
      console.log(`  Area: ${ev.area}`);
      console.log(`  Source: ${ev.source}`);
      console.log(`  URL: ${ev.url}`);
    });
    return events;
  } catch (error) {
    console.error('❌ Error:', error.message);
    throw error;
  }
}

test().catch(console.error);
EOF
node test_kh_ts.mjs

